73	/**
74	 * Concludes the issue: closes an agent-opened one, asks the author to close a
75	 * person-opened one.
76	 *
77	 * Neither branch fails, and the caller ends the session on both. Who opened the
78	 * issue is this function's question to ask, not its caller's to handle — see
79	 * `domain/work/close-request.ts` for the reports that came out of answering it
80	 * the other way.
81	 */
82	export async function concludeIssue(issue: number, reason: string, summary: string): Promise<ConcludeIssueResult> {
83	  const repo = process.env.GITHUB_REPOSITORY ?? "";
84	  // The exit code decides, not just the presence of output. An unread author is
85	  // not a human author: closing the issue outright and telling a person "this was
86	  // opened directly by a human" are different acts, and picking either one on a
87	  // failed lookup asserts something this did not determine. The same question is
88	  // asked fail-loud in `mcp/github.ts` via `ghJsonOrThrow`.
89	  const { code, stdout } = gh("issue", "view", String(issue), "--repo", repo, "--json", "author");
90	  if (code !== 0) {
91	    throw new Error(
92	      `Could not read the author of issue #${issue}, so this cannot tell whether closing it is yours to do.`,
93	    );
94	  }
95	  const authorInfo = stdout ? (JSON.parse(stdout) as GhIssueAuthor) : {};
96	  // Absent field still means "treat as a person", which is the cautious half of
97	  // the pair: it hands the decision to someone rather than taking it. The rule is
98	  // `domain/work/actor.ts`'s, shared with every other reader of the same fact.
99	  const isBot = !isHumanAuthor(authorInfo.author?.is_bot);
100	
101	  let body = `Atomaton: the agent on this issue considers its work complete.\n\n**Reason:** ${reason}`;
102	  if (summary) {
103	    body += `\n\n${summary}`;
104	  }
105	
106	  if (!isBot) {
107	    // The request goes above the reason and summary, not after them. It is the
108	    // only sentence in the comment addressed to the person reading it.
109	    //
110	    // `ended: "done"` because this IS the turn ending: the run is over, the issue stays
111	    // open, and the ball is with the person who was just asked to close it. Leaving it
112	    // out left the node's last turn event as the `asked` that started the run, so the
113	    // guard read "the ball is with an agent" and DELETED the person's next comment —
114	    // which, on this path, is their agreement to close the issue. The failure notice's
115	    // half is #90's; this is the same defect here, in code written to fix #90. See
116	    // `turn-comment.ts`.
117	    const request = closeRequestComment({ notify: resolveNotify(repo, issue), body });
118	    const posted = gh("issue", "comment", String(issue), "--repo", repo, "--body", turnCommentBody({ ended: "done", audience: "person", body: request, ...endingIdentity() }));
119	    mustSucceed(posted, `comment on issue #${issue}`);
120	    // stderr, where the tool's own decisions belong. Putting it in the result is
121	    // what put it in the agent's report.
122	    console.error(`close requested: issue=#${issue} (opened by a person, left open for them)`);
123	    return { outcome: "close-requested", commentId: commentIdFromUrl(posted.stdout) };
124	  }
125	
126	  // The conclusion itself. `audience: "model"` because this is what the parent agent
127	  // reads when it aggregates what its children found — the reason and the summary are
128	  // written for that reader, and were reaching it only because an untagged comment is
129	  // included by default rather than by anybody deciding.
130	  //
131	  // `ended: "done"` for the same reason as the branch above: this run is over and the
132	  // session ends on this call. It closes the issue just below, so the thread has an
133	  // answer either way — but a close is not an event to `domain/work/thread.ts`, and the
134	  // turn's ending has to be written down rather than inferred from one.
135	  const posted = gh("issue", "comment", String(issue), "--repo", repo, "--body", turnCommentBody({ ended: "done", audience: "model", body, ...endingIdentity() }));
